/* ==UserStyle==
@name           GitHub
@namespace      github.com/seenukarthi/Stylus
@version        1.0.0
@description    This Style Sheet for Github and Gist.
@author         Karthikeyan Vaithilingam
==/UserStyle== */
@-moz-document domain("github.com") {

    :root {
        --fontStack-sansSerif: var(--vknDefaultFontFamily);
        --fontStack-sansSerifDisplay: var(--vknDefaultFontFamily);
        --fontStack-system: var(--vknDefaultFontFamily);
        --fontStack-monospace: var(--vknMonoFontFamily);
    }

    .react-code-lines,
    .react-code-text,
    .react-blob-print-hide,
    .mb-1 > *,
    .input-monospace,
    .blob-code-inner,
    .react-directory-rowm .markdown-body .highlight pre,
    .markdown-body pre {
        font-family: var(--vknMonoFontFamily) !important;
    }

    div[style="overflow:auto;"] {
        background-color: #f00;
    }

    .markdown-body {
        font-family: var(--vknDefaultFontFamily) !important;
    }

    span[class^='TitleHeader-'],
    span[class*=' TitleHeader-'],
    span[class^='CommitHeader-'],
    span[class*=' CommitHeader-'],
    .text-mono {
        font-family: var(--vknMonoFontFamily) !important;
    }

    .Link--primary {
        font-weight: 500;
    }

    .container-xl {
      max-width: 95%;
    }

    @layer primer-react {
      .prc-PageLayout-Content-xWL-A:where([data-width="large"]) {
        max-width: 100%;
      }
    }
}

@-moz-document url-prefix("https://gist.github.com") {
    .blob-code *,
    .input-monospace {
        font-family: var(--vknMonoFontFamily) !important;
    }
}
